/*
 * A134043  Complete list of solutions to y^2 = x^3 + 113; sequence gives y
 *          values.
 * https://oeis.org/A134043
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, fini, full
 * Formula:   not stated
 * Range:     u8 n <= 5, u16 n <= 6, u32 n <= 6, u64 n <= 6, u128 n <= 6,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence: a(n) = positive y-values of integer solutions to y^2 = x^3 + 113. */
/* Generated by searching all integer x with |x| <= 1,000,000. */

#include <stdint.h>
#include <stddef.h>
#include <stdlib.h>

static int64_t isqrt64(int64_t n)
{
    if (n < 0) return -1;
    int64_t low = 0, high = 3037000499;   /* floor(sqrt(INT64_MAX)) */
    int64_t ans  = 0;
    while (low <= high) {
        int64_t mid = (low + high) >> 1;
        if (mid != 0 && mid > n / mid) {    /* mid*mid > n */
            high = mid - 1;
        } else {
            ans  = mid;
            low  = mid + 1;
        }
    }
    return ans;
}

static int seqcmp(const void *a, const void *b)
{
    seq_t va = *(const seq_t *)a;
    seq_t vb = *(const seq_t *)b;
    if (va < vb) return -1;
    if (va > vb) return  1;
    return 0;
}

static seq_t *solutions   = NULL;
static size_t sol_count   = 0;
static size_t sol_cap     = 0;

static void compute_all(void)
{
    if (solutions != NULL) return;           /* already computed */
    const int MAX_X = 1000000;               /* safety bound */
    sol_cap     = 16;
    solutions   = (seq_t *)malloc(sol_cap * sizeof(seq_t));
    if (!solutions) return;                  /* allocation failed */

    for (int x = -MAX_X; x <= MAX_X; ++x) {
        int64_t cube = (int64_t)x * (int64_t)x * (int64_t)x;
        int64_t val  = cube + 113;
        if (val < 0) continue;              /* RHS must be non‑negative */
        int64_t y = isqrt64(val);
        if (y * y == val) {                 /* perfect square found */
            if (sol_count == sol_cap) {
                sol_cap *= 2;
                seq_t *tmp = (seq_t *)realloc(solutions, sol_cap * sizeof(seq_t));
                if (!tmp) break;            /* allocation failed */
                solutions = tmp;
            }
            solutions[sol_count++] = (seq_t)y;
        }
    }
    if (sol_count > 1)
        qsort(solutions, sol_count, sizeof(seq_t), seqcmp);
}

/* Return a(n) for n >= 1. 0 is returned if n exceeds the number of known terms. */
seq_t a(idx_t n)
{
    if (n == 0) return 0;
    compute_all();
    if (n > sol_count) return 0;
    return solutions[n - 1];
}
